ect_id": "5a040608-3a45-5b08-b5ff-298046767440", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜晏球：集将下令者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：丁卯，战于城南。晏球集诸将校令之曰：“王都轻而骄，可一战擒也。今日，诸君报国之时也。悉去弓矢，以短兵击之，回顾者斩！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f494a922-7c05-52b6-b213-f34a5c9a4554", "subject_id": "159f8e77-2ede-5886-8c99-80d5a7b48103", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "description", "claim_text": "唐骑先冲入敌阵，大败王都与契丹军。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：于是骑兵先进，奋，楇挥剑，直冲其陈，大破之，；核对说明：主奋，楇挥剑有标点及字形疑，原字保留，只概录骑军先冲不改原句；不凭主未名骑军自动猜具体左右将。", "status": "draft", "id": "6225ed56-ae1b-5b6f-802d-3e50efcbafaa", "subject_id": "64ec124c-d660-54c3-bb8c-957516463d2b", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "928年五月丁卯", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：于是骑兵先进，奋，楇挥剑，直冲其陈，大破之，；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ef188af7-5394-5a10-807c-3babe3208e6a", "subject_id": "64ec124c-d660-54c3-bb8c-957516463d2b", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "杜晏球：骑军胜战统领。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：于是骑兵先进，奋，楇挥剑，直冲其陈，大破之，；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b311c299-7c92-519d-8faa-2a80c11061ef", "subject_id": "9316eed8-70a1-51d3-b56d-0c379fd3d8a1", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "description", "claim_text": "新王传补符彦卿左军、高行珪右军及中军骑士抱马项冲敌，敌大败。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001728；EPUB电子本，纸本及异文待核", "note": "原文：晏球立高岡，號令諸將皆橐弓矢、用短兵，回顧者斬。符彥卿以左軍攻其左，高行珪以右軍攻其右，[2]中軍騎士抱馬項馳入都軍，都遂大敗，；核对说明：新高行珪与旧嘉山概叙高行周不同人名保留，未合并或硬推同役同人；底本[2]注标原样保留，动作是史载不编现代兵种战法细节。", "status": "draft", "id": "dd5aa155-57ad-5d84-97b8-976ed59abb30", "subject_id": "64ec124c-d660-54c3-bb8c-957516463d2b", "source_id": "1475b3ce-05ee-52b9-924e-867160fabe6b"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "旧明宗纪五月壬申记王晏球奏五月二十一日于曲阳大败定州军及契丹，斩获数千。", "citation": "《旧五代史》卷三十九，段落 jiu-wudaishi-205deb4a7860-p001151；EPUB电子本，纸本及异文待核", "note": "原文：壬申，王晏球奏，今月二十一日，大破定州賊軍及契丹於曲陽，斬獲數千人，；核对说明：壬申为奏报日、二十一为所报行动日，与主丁卯分别保留原纪日，不自动换算干支或把奏报日等行动日。", "status": "draft", "id": "c726c4b9-01a5-5c22-9951-e0b44bdde72b", "subject_id": "64ec124c-d660-54c3-bb8c-957516463d2b", "source_id": "08077fe9-0d0e-51f4-b716-1294645fe4ab"}, {"subject_table": "event", "field_path": "description", "claim_text": "曲阳败军尸遍野，契丹死者过半，王都秃馁以数骑逃脱。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：僵尸蔽野；契丹死者过半，馀众北走；都与秃馁得数骑，仅免。；核对说明：主过半为概述，不用前五千计算确定死者人数；数骑为逃随人数，不等只存这几人；王都未被擒。", "status": "draft", "id": "2dcdb3ec-88b7-5a01-8703-d9aa820da6e2", "subject_id": "6de81492-4342-58c8-92e9-d1c2a0f4850e", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "928年五月丁卯交战后", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：僵尸蔽野；契丹死者过半，馀众北走；都与秃馁得数骑，仅免。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "ea0db8dc-1287-5170-adea-f890e3d8031b", "subject_id": "6de81492-4342-58c8-92e9-d1c2a0f4850e", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "王都：以数骑逃脱者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：僵尸蔽野；契丹死者过半，馀众北走；都与秃馁得数骑，仅免。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "9290f55a-27af-5989-9105-f2f890c77f77", "subject_id": "1bf8b848-6915-5791-8f3e-a82e00aed290", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "秃馁：同逃者。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：僵尸蔽野；契丹死者过半，馀众北走；都与秃馁得数骑，仅免。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "94f33502-22c2-50c8-9f67-3706ca12b0c4", "subject_id": "da52f657-7de3-53d7-b93e-171c8183ed7e", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "description", "claim_text": "新王氏传同记曲阳大败后王都与秃馁以数骑逃走，闭城不出。", "citation": "《新五代史》卷三十九，段落 xin-wudaishi-b08f244b9241-p001376；EPUB电子本，纸本及异文待核", "note": "原文：與都及契丹戰，大敗之曲陽，都及禿餒得數騎遯去，閉城不復出。；核对说明：补回城闭守结果，未提前翌年自焚与秃馁被俘。", "status": "draft", "id": "717fbb8d-3cef-51de-99d6-a7d0279981ff", "subject_id": "6de81492-4342-58c8-92e9-d1c2a0f4850e", "source_id": "d60aac22-2dfd-5717-aa0e-d37624d22cdc"}, {"subject_table": "event", "field_path": "description", "claim_text": "新王传形容曲阳至定州横尸弃甲六十余里，王都与秃馁入城不再出战。", "citation": "《新五代史》卷四十六，段落 xin-wudaishi-b08f244b9241-p001728；EPUB电子本，纸本及异文待核", "note": "原文：都遂大敗，自曲陽至定州，橫尸棄甲六十餘里。都與禿餒入城，不敢復出。；核对说明：六十余里为史载败军场面概数，不精确配地图尸体分布；闭守非定州已被唐军占领。", "status": "draft", "id": "b62b1649-b55c-550a-b822-433c43c6120d", "subject_id": "6de81492-4342-58c8-92e9-d1c2a0f4850e", "source_id": "1475b3ce-05ee-52b9-924e-867160fabe6b"}, {"subject_table": "event", "field_path": "description", "claim_text": "赵德钧邀击契丹北逃军，史书记几无幸免。", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：卢龙节度使赵德钧邀击契丹，北走者殆无孑遗。；核对说明：殆无是近乎无人幸免的叙述，不能写确定全部歼灭或混后七月惕隐援军被截事件。", "status": "draft", "id": "e585b334-216c-5c9c-9097-aedb731d6f25", "subject_id": "a95e297d-edac-59ed-b62b-aa2810d7e75d", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "928年五月曲阳败军北走后，确日未载", "citation": "卷276·天成三年（928）·zztj-v276-y0928-p017·原文件第49行", "note": "原文：卢龙节度使赵德钧邀击契丹，北走者殆无孑遗。；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "9dced1b7-bd2a-5899-a079-67a86d5827f6", "subject_id": "a95e297d-edac-59ed-b62b-aa2810d7e75d", "source_id": "b0aea13f-d79c-515b-9cbd-e297bdd27ef4"}, {"subject_table": "person_event", "field_path": 